mapper.sql:
FROM SERVICE_REQUEST s JOIN CATEGORY category ON category.CAT_SN = s.CAT_SN JOIN USERS requester ON requester.USR_SN = s.USR_SN JOIN CMM_CODE status_code ON status_code.CMM_CD = s.SVC_REQ_STATUS_CD WHERE 1 = 1
AND (s.SVC_REQ_TTL LIKE CONCAT('%', #{condition.keyword}, '%') OR requester.USR_NM LIKE CONCAT('%', #{condition.keyword}, '%') OR CAST(s.SVC_REQ_SN AS CHAR) LIKE CONCAT('%', #{condition.keyword}, '%') OR CONCAT('#', s.SVC_REQ_SN) LIKE CONCAT('%', #{condition.keyword}, '%'))
AND s.CAT_SN = #{condition.categorySn}
AND s.SVC_REQ_STATUS_CD = #{condition.statusCode}
AND s.SVC_REQ_REG_DT >= #{condition.registeredFrom}
AND s.SVC_REQ_REG_DT < DATE_ADD(#{condition.registeredTo}, INTERVAL 1 DAY)

mapper.select:
/* ServiceRequestMapper.findServiceRequestTitles */
SELECT SVC_REQ_SN, SVC_REQ_TTL
  FROM SERVICE_REQUEST
 WHERE SVC_REQ_USE_YN = 'Y'
   AND SVC_REQ_SN IN

    #{svcReqSn}

/* ServiceRequestMapper.searchServiceRequests */ SELECT s.SVC_REQ_SN, s.USR_SN, s.CAT_SN, s.SVC_REQ_FORM_TMPL_SN, c.CAT_NM, s.SVC_REQ_TTL, s.SVC_REQ_CN, s.SVC_REQ_BDGT_AMT, s.SVC_REQ_STATUS_CD, s.SVC_REQ_REG_DT, s.SVC_REQ_UPDT_DT, ( SELECT CONCAT('/api/service-requests/', image.SVC_REQ_SN, '/images/', image.FL_SN) FROM SVC_REQ_IMAGE image JOIN FILES file ON file.FL_SN = image.FL_SN WHERE image.SVC_REQ_SN = s.SVC_REQ_SN AND file.FL_USE_YN = 'Y' ORDER BY image.SVC_REQ_IMG_SORT_NO ASC, image.FL_SN ASC LIMIT 1 ) AS THUMBNAIL_URL FROM SERVICE_REQUEST s JOIN CATEGORY c ON c.CAT_SN = s.CAT_SN WHERE s.SVC_REQ_STATUS_CD = 'SVCC0002' AND s.SVC_REQ_USE_YN = 'Y'
AND (s.SVC_REQ_TTL LIKE CONCAT('%', #{keyword}, '%') OR s.SVC_REQ_CN LIKE CONCAT('%', #{keyword}, '%'))
AND s.CAT_SN = #{categorySn}
AND s.SVC_REQ_BDGT_AMT >= #{minBudget}
AND s.SVC_REQ_BDGT_AMT <= #{maxBudget}
ORDER BY
s.SVC_REQ_BDGT_AMT DESC, s.SVC_REQ_REG_DT DESC s.SVC_REQ_REG_DT DESC

mapper.update:
/* ServiceRequestMapper.markServiceRequestMatched */
UPDATE SERVICE_REQUEST
   SET SVC_REQ_STATUS_CD = 'SVCC0003',
       SVC_REQ_UPDT_ID   = #{updtId}
 WHERE SVC_REQ_SN = #{svcReqSn}
   AND USR_SN = #{usrSn}
   AND SVC_REQ_STATUS_CD = 'SVCC0002'
   AND SVC_REQ_USE_YN = 'Y'

/* ServiceRequestMapper.closeServiceRequest */
UPDATE SERVICE_REQUEST
   SET SVC_REQ_STATUS_CD = 'SVCC0004',
       SVC_REQ_UPDT_ID   = #{updtId}
 WHERE SVC_REQ_SN = #{svcReqSn}
   AND USR_SN     = #{usrSn}
   AND SVC_REQ_STATUS_CD = 'SVCC0002'

UPDATE SERVICE_REQUEST
   SET SVC_REQ_STATUS_CD = 'SVCC0004',
       SVC_REQ_UPDT_ID = #{updtId}
 WHERE SVC_REQ_SN = #{svcReqSn}
   AND SVC_REQ_STATUS_CD = 'SVCC0002'

mapper.select:
/* ServiceRequestMapper.findServiceRequestEntityById */
SELECT SVC_REQ_SN, USR_SN, CAT_SN, SVC_REQ_FORM_TMPL_SN, SVC_REQ_TTL, SVC_REQ_CN, SVC_REQ_BDGT_AMT, SVC_REQ_STATUS_CD,
       SVC_REQ_USE_YN, SVC_REQ_REG_DT, SVC_REQ_UPDT_DT, SVC_REQ_REG_ID, SVC_REQ_UPDT_ID
  FROM SERVICE_REQUEST
 WHERE SVC_REQ_SN = #{svcReqSn}

/* ServiceRequestMapper.findServiceRequestEntityByIdForUpdate */
SELECT SVC_REQ_SN, USR_SN, CAT_SN, SVC_REQ_FORM_TMPL_SN, SVC_REQ_TTL, SVC_REQ_CN, SVC_REQ_BDGT_AMT, SVC_REQ_STATUS_CD,
       SVC_REQ_USE_YN, SVC_REQ_REG_DT, SVC_REQ_UPDT_DT, SVC_REQ_REG_ID, SVC_REQ_UPDT_ID
  FROM SERVICE_REQUEST
 WHERE SVC_REQ_SN = #{svcReqSn}
 FOR UPDATE

mapper.update:
/* ServiceRequestMapper.deleteServiceRequest */
UPDATE SERVICE_REQUEST
   SET SVC_REQ_USE_YN  = 'N',
       SVC_REQ_UPDT_ID = CAST(#{usrSn} AS CHAR)
 WHERE SVC_REQ_SN = #{svcReqSn}
   AND USR_SN     = #{usrSn}
